"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[93662],{93662:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/if-we-cannot-moveat-the-speeod-of-light.png\\"\\n          title=\\"우리가 빛의 속도로 갈 수 없다면\\"\\n          author=\\"김초엽\\"\\n          publisher=\\"허블\\"\\n          publishedDate=\\"2019-06-24\\"\\n          isbn=\\"9791190090018\\"\\n          rating=4\\n          tags=\\"SF\\"\\n        />\\n</center>\\n\\n## Review\\n독서 모임에서 추천받아서 읽은 책이다.  \\n책을 추천받았다기보다는 <mark>김초엽</mark> 작가님을 추천받았다.  \\n단편집이라 작가님의 스타일을 한 권에 느낄 수 있어서 좋았다. 다른 작품도 읽어봐야겠다.  \\n<br>\\n```공생가설```이 신선했다. 유년기 기억 상실증이 일어나는 현상에 대한 재미있는 가설이었다.  \\n```관내분실```에 나오는 도서관은 미래에 가능할 것 같은 기술이었다.  \\n<br>\\n기술이 아닌 ```기술을 사용하는 인간```을 중심에 둔 이야기"}')}}]);